from pathlib import Path

CSS=Path('styles/app-src/styles-part-01.part.css')
START='/* Verify Deck reference-fidelity shell — canonical owner */'
END_HINT='\n/* '
css=CSS.read_text()
start=css.find(START)
if start<0: raise SystemExit('canonical Verify owner marker not found')
next_comment=css.find(END_HINT,start+len(START))
if next_comment<0: next_comment=len(css)
NEW=r'''/* Verify Deck reference-fidelity shell — canonical owner */
#setup{position:relative;isolation:isolate;padding:0 2px 18px;--verify-gold:#b99650;--verify-gold-mid:#d1ad62;--verify-gold-bright:#f4dfa6;--verify-gold-dark:#60451f;--verify-ink:#02070b;--verify-panel:#061019;--verify-line:rgba(205,168,91,.48)}
#setup .verifyShell{position:relative;overflow:hidden;margin:8px 0 18px;padding:118px clamp(20px,5.4vw,46px) 25px;border:1px solid color-mix(in srgb,var(--deck-a,#58b9ff) 11%,var(--verify-gold-mid));border-radius:16px;background:radial-gradient(120% 52% at 12% 11%,color-mix(in srgb,var(--deck-a,#58b9ff) 18%,transparent),transparent 50%),radial-gradient(120% 52% at 88% 11%,color-mix(in srgb,var(--deck-b,#ff654d) 18%,transparent),transparent 50%),linear-gradient(180deg,#08121b 0%,#040b11 38%,#02070b 100%);box-shadow:0 34px 85px rgba(0,0,0,.66),0 3px 0 rgba(255,255,255,.025) inset,0 0 0 4px #02070b inset,0 0 0 5px rgba(222,184,103,.14) inset,0 0 70px color-mix(in srgb,var(--deck-glow,rgba(82,184,255,.2)) 12%,transparent)}
#setup .verifyShell:after{content:"";position:absolute;inset:14px;pointer-events:none;border-radius:9px;background:repeating-linear-gradient(0deg,rgba(255,255,255,.008) 0 1px,transparent 1px 4px);mix-blend-mode:soft-light;opacity:.48;z-index:0}
#setup .verifyFrame{position:absolute;inset:9px;border:1px solid rgba(205,168,91,.5);border-radius:10px;pointer-events:none;z-index:6;box-shadow:0 0 0 1px rgba(24,14,5,.8) inset,0 0 0 3px rgba(205,168,91,.045),0 0 18px rgba(214,175,92,.05) inset}
#setup .verifyFrame:before,#setup .verifyFrame:after{content:"";position:absolute;left:28px;right:28px;height:5px;border-top:1px solid rgba(244,223,166,.72);border-bottom:1px solid rgba(82,58,24,.78);background:linear-gradient(90deg,transparent,rgba(205,168,91,.14) 18%,rgba(244,223,166,.14) 50%,rgba(205,168,91,.14) 82%,transparent);box-shadow:0 1px 8px rgba(236,196,110,.08)}
#setup .verifyFrame:before{top:7px}#setup .verifyFrame:after{bottom:7px;transform:scaleY(-1)}
#setup .verifyCorner{position:absolute;width:28px;height:28px;display:grid;place-items:center;color:var(--verify-gold-bright);font-family:Georgia,serif;font-size:17px;text-shadow:0 0 9px rgba(239,211,145,.42);filter:drop-shadow(0 1px 0 #2c1a08)}
#setup .verifyCorner.tl{left:-12px;top:-13px}#setup .verifyCorner.tr{right:-12px;top:-13px}#setup .verifyCorner.bl{left:-12px;bottom:-13px}#setup .verifyCorner.br{right:-12px;bottom:-13px}
#setup .verifyArcaneRail{position:absolute;top:186px;bottom:118px;z-index:1;width:19px;overflow:hidden;font:10px/2.24 Georgia,serif;letter-spacing:.09em;text-align:center;opacity:.31;pointer-events:none;text-shadow:0 0 7px currentColor}
#setup .verifyArcaneRailLeft{left:14px;color:color-mix(in srgb,var(--deck-a,#5db8ff) 60%,#8e9c67)}#setup .verifyArcaneRailRight{right:14px;color:color-mix(in srgb,var(--deck-b,#ff654d) 57%,#b38245)}
#setup .verifyManaAtmosphere{position:absolute;z-index:0;left:26px;right:26px;top:53px;height:240px;overflow:hidden;pointer-events:none;filter:saturate(1.15)}
#setup .manaFlow{position:absolute;top:48px;width:62%;height:132px;border-radius:50%;filter:blur(21px);opacity:.46;animation:verifyManaBreathe 7.5s ease-in-out infinite alternate}
#setup .manaFlow.cool{left:-9%;background:radial-gradient(ellipse at center,color-mix(in srgb,var(--deck-a,#5db8ff) 58%,#dcecff),transparent 67%);transform:rotate(-8deg)}#setup .manaFlow.warm{right:-9%;background:radial-gradient(ellipse at center,color-mix(in srgb,var(--deck-b,#ff654d) 58%,#ff7a41),transparent 67%);transform:rotate(8deg);animation-delay:-3.8s}
@keyframes verifyManaBreathe{0%{opacity:.32;filter:blur(23px) saturate(.95)}100%{opacity:.55;filter:blur(18px) saturate(1.22)}}
#setup .verifyHero{position:relative;z-index:3;text-align:center;padding-top:66px}
#setup .verifyManaWheel{position:absolute;left:50%;top:-92px;transform:translateX(-50%);width:154px;height:154px;border-radius:50%;border:2px solid var(--verify-gold-bright);background:conic-gradient(from -18deg,#ddd8c5 0 19.5%,#0e6795 20% 39.5%,#10151a 40% 59.5%,#873126 60% 79.5%,#2c6540 80% 100%);box-shadow:0 0 0 2px #2d1e0a,0 0 0 6px #071018,0 0 0 8px rgba(239,211,145,.68),0 18px 42px rgba(0,0,0,.62),0 0 38px color-mix(in srgb,var(--deck-a,#5db8ff) 20%,transparent);filter:drop-shadow(0 4px 4px rgba(0,0,0,.48))}
#setup .verifyManaWheel:before{content:"";position:absolute;inset:16px;border-radius:50%;border:1px solid rgba(247,237,208,.47);box-shadow:inset 0 0 0 2px rgba(0,0,0,.38),inset 0 0 28px rgba(0,0,0,.55),0 0 10px rgba(240,208,137,.06)}
#setup .verifyManaWheel:after{content:"";position:absolute;inset:5px;border-radius:50%;border:1px dashed rgba(255,235,183,.22)}
#setup .manaCore{position:absolute;left:50%;top:50%;width:39px;height:39px;transform:translate(-50%,-50%) rotate(45deg);border:1px solid rgba(244,223,166,.88);background:linear-gradient(135deg,#101a21,#03070a 66%);box-shadow:0 0 0 2px #2f210d,0 0 21px rgba(239,211,145,.29),inset 1px 1px 0 rgba(255,255,255,.1)}
#setup .manaMark{position:absolute;z-index:2;display:grid;place-items:center;width:34px;height:34px;border-radius:50%;font-family:Georgia,serif;font-size:20px;font-weight:700;color:#0a0d0f;text-shadow:0 1px rgba(255,255,255,.2);filter:drop-shadow(0 2px 1px rgba(0,0,0,.5))}
#setup .manaMark.white{left:60px;top:10px}#setup .manaMark.blue{right:9px;top:55px;color:#e2f4ff}#setup .manaMark.black{right:29px;bottom:12px;color:#dcdede}#setup .manaMark.red{left:28px;bottom:12px;color:#ffd5bf}#setup .manaMark.green{left:8px;top:55px;color:#dcf4d9}
#setup h2{font-family:Georgia,'Times New Roman',serif;color:#f7f0df;font-size:clamp(39px,9.2vw,60px);font-weight:700;line-height:1.01;letter-spacing:.008em;margin:10px 0 14px;text-shadow:0 2px 0 #1b1107,0 4px 18px rgba(0,0,0,.72),0 0 22px rgba(239,211,145,.1)}
#setup .verifyLead{margin:0 auto 33px;max-width:555px;color:#b9bcc0;font-size:clamp(13px,3.25vw,17px);line-height:1.58;text-shadow:0 2px 5px rgba(0,0,0,.45)}
#setup .verifyDivider{position:relative;z-index:3;display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:12px;margin:13px 2px 14px;color:var(--verify-gold-bright)}
#setup .verifyDivider:before,#setup .verifyDivider:after{content:"";height:3px;border-top:1px solid rgba(205,168,91,.48);border-bottom:1px solid rgba(74,49,18,.72);background:linear-gradient(90deg,transparent,rgba(205,168,91,.12))}#setup .verifyDivider:after{background:linear-gradient(90deg,rgba(205,168,91,.12),transparent)}
#setup .verifyDivider b{font-family:Georgia,'Times New Roman',serif;font-size:12px;letter-spacing:.26em;font-weight:700;color:#ece1c7;text-shadow:0 1px 0 #000}#setup .verifyDivider span{font-size:9px;color:var(--verify-gold);filter:drop-shadow(0 0 5px rgba(234,199,119,.28))}
#setup .verifyDeckPanel{position:relative;z-index:3;padding:5px;border:1px solid rgba(205,168,91,.27);border-radius:13px;background:linear-gradient(145deg,rgba(91,62,25,.24),rgba(0,0,0,.3));box-shadow:0 1px 0 rgba(255,255,255,.03) inset,0 10px 28px rgba(0,0,0,.25)}
#setup textarea{min-height:292px;padding:18px 18px 39px;border:1px solid rgba(205,168,91,.52);border-radius:9px;background:radial-gradient(circle at 20% 0%,color-mix(in srgb,var(--deck-a,#5db8ff) 4%,transparent),transparent 28%),linear-gradient(180deg,#061019,#02080d);color:#edf1f3;font-size:15px;line-height:1.48;resize:vertical;box-shadow:inset 0 0 0 1px rgba(0,0,0,.8),inset 0 8px 24px rgba(0,0,0,.42),0 1px 0 rgba(255,255,255,.035);transition:border-color .18s,box-shadow .18s,background .18s}
#setup textarea::placeholder{color:#858a8e}#setup textarea:hover{border-color:rgba(226,190,111,.68)}#setup textarea:focus,#setup select:focus{outline:none;border-color:color-mix(in srgb,var(--deck-a,#5db8ff) 42%,var(--verify-gold-bright));box-shadow:inset 0 0 0 1px rgba(0,0,0,.72),0 0 0 2px color-mix(in srgb,var(--deck-a,#5db8ff) 18%,transparent),0 0 24px color-mix(in srgb,var(--deck-glow,rgba(82,184,255,.2)) 22%,transparent)}
#setup .deckCharCount{position:absolute;right:18px;bottom:14px;color:#92979b;font-size:11px;letter-spacing:.04em;pointer-events:none}
#setup .legalityToolbar{position:relative;z-index:3;display:grid;grid-template-columns:minmax(0,1fr) minmax(142px,200px);align-items:center;gap:12px;margin:13px 0 24px;padding:10px 12px;border:1px solid rgba(205,168,91,.25);border-radius:9px;background:linear-gradient(180deg,rgba(10,20,28,.86),rgba(3,10,15,.9));box-shadow:inset 0 1px rgba(255,255,255,.025)}
#setup .legalityToolbar label{font-size:9px;color:#adb1b5;letter-spacing:.17em}#setup .legalityToolbar select{padding:9px 10px;border:1px solid rgba(205,168,91,.39);border-radius:7px;background:linear-gradient(180deg,#0a151d,#050c11);color:#eee5d0;box-shadow:inset 0 1px rgba(255,255,255,.025)}
#setup .verifyImportDivider{margin-top:6px}
#setup .importActions{position:relative;z-index:3;display:grid;grid-template-columns:1fr 1fr;gap:11px}
#setup .verifyImportCard,#setup .verifyVaultRow{display:grid;align-items:center;text-align:left;color:#efe9d9;border:1px solid rgba(205,168,91,.46);background:linear-gradient(155deg,rgba(12,24,33,.97),rgba(3,10,15,.99));box-shadow:inset 0 1px rgba(255,255,255,.035),inset 0 -1px rgba(0,0,0,.8),0 9px 24px rgba(0,0,0,.24);transition:transform .16s ease,border-color .16s ease,box-shadow .16s ease,background .16s ease}
#setup .verifyImportCard{grid-template-columns:54px minmax(0,1fr);gap:12px;min-height:88px;padding:14px;border-radius:11px}
#setup .verifyImportCard:hover,#setup .verifyVaultRow:hover{transform:translateY(-1px);border-color:rgba(236,202,125,.7);background:linear-gradient(155deg,color-mix(in srgb,var(--deck-a,#58b9ff) 5%,#0c1821),#030a0f);box-shadow:inset 0 1px rgba(255,255,255,.05),0 13px 30px rgba(0,0,0,.3),0 0 18px color-mix(in srgb,var(--deck-glow,rgba(82,184,255,.2)) 10%,transparent)}
#setup .verifyImportCard:active,#setup .verifyVaultRow:active{transform:translateY(1px) scale(.995)}
#setup .verifyImportCard b,#setup .verifyVaultRow b{display:block;font-family:Georgia,'Times New Roman',serif;font-size:18px;font-weight:500;color:#f3ead7;text-shadow:0 1px 0 #000}#setup .verifyImportCard small,#setup .verifyVaultRow small{display:block;margin-top:4px;color:#92989c;font-size:11px;font-weight:500}
#setup .verifyActionIcon{display:grid;place-items:center;width:48px;height:48px;border-radius:50%;border:1px solid rgba(220,183,101,.66);background:radial-gradient(circle at 34% 26%,rgba(244,223,166,.2),rgba(92,63,26,.16) 24%,#071018 68%);color:#edcd82;font-family:Georgia,serif;font-size:26px;box-shadow:inset 0 0 0 3px rgba(0,0,0,.38),inset 1px 1px rgba(255,255,255,.07),0 2px 5px rgba(0,0,0,.5);text-shadow:0 1px 0 #3a230b}
#setup .verifyVaultRow{position:relative;z-index:3;grid-template-columns:54px minmax(0,1fr) auto;gap:12px;width:100%;min-height:76px;margin-top:11px;padding:12px 15px;border-radius:11px}#setup .verifyVaultRow>strong{font-size:29px;font-weight:300;color:#dfbd70;text-shadow:0 1px #000}
#setup .physicalDeckNote{position:relative;z-index:3;margin:11px 0 13px;padding:7px 10px;border:0;background:transparent;color:#878e93;font-size:9px;letter-spacing:.095em;text-align:center}
#setup .verifyDeckCta{position:relative;z-index:3;display:grid;grid-template-columns:58px minmax(0,1fr);align-items:center;gap:14px;width:100%;min-height:104px;padding:15px 22px;border:1px solid rgba(244,223,166,.78);border-radius:13px;background:radial-gradient(circle at 50% -25%,color-mix(in srgb,var(--deck-a,#58b9ff) 24%,transparent),transparent 55%),linear-gradient(180deg,#0b2434 0%,#071824 48%,#041019 100%);color:#f8f2e2;box-shadow:0 0 0 2px #35240d,0 0 0 5px rgba(6,12,16,.95),0 0 0 6px rgba(205,168,91,.42),0 15px 35px rgba(0,0,0,.38),inset 0 1px rgba(255,255,255,.08),inset 0 -12px 25px rgba(0,0,0,.24);transition:transform .16s ease,box-shadow .2s ease,filter .2s ease}
#setup .verifyDeckCta:hover{transform:translateY(-2px);filter:brightness(1.06);box-shadow:0 0 0 2px #493116,0 0 0 5px rgba(6,12,16,.96),0 0 0 6px rgba(236,200,119,.58),0 19px 42px rgba(0,0,0,.45),0 0 28px color-mix(in srgb,var(--deck-glow,rgba(82,184,255,.2)) 25%,transparent),inset 0 1px rgba(255,255,255,.1),inset 0 -12px 25px rgba(0,0,0,.2)}#setup .verifyDeckCta:active{transform:translateY(1px) scale(.997)}
#setup .verifyShield{display:grid;place-items:center;width:56px;height:62px;border:1px solid rgba(238,207,136,.74);clip-path:polygon(50% 0,92% 14%,86% 72%,50% 100%,14% 72%,8% 14%);background:linear-gradient(150deg,#17334a,#07131d 66%);color:#f1d07d;font-size:25px;text-shadow:0 0 10px rgba(239,211,145,.35);box-shadow:inset 0 0 18px rgba(0,0,0,.3)}
#setup .verifyDeckCta b{display:block;font-family:Georgia,'Times New Roman',serif;font-size:clamp(27px,6.5vw,38px);font-weight:500;line-height:1.03;text-shadow:0 2px 0 #000,0 0 16px rgba(238,210,146,.08)}#setup .verifyDeckCta small{display:block;margin-top:6px;color:#bec4c8;font-size:11px;font-weight:500;letter-spacing:.01em}
#setup #vr{position:relative;z-index:3;margin-top:17px;padding-top:16px;border-top:1px solid rgba(205,168,91,.23)}#setup .cmdPick{border-color:rgba(205,168,91,.34);background:linear-gradient(180deg,#07131b,#040b10)}#setup .verifyContinueGrid{margin-top:11px}
#setup .verifyPrivacy{position:relative;z-index:3;display:flex;justify-content:center;align-items:center;flex-wrap:wrap;gap:7px;margin:23px 0 0;color:#858b8f;font-size:10px;text-align:center}#setup .verifyPrivacy>b{color:#c6a75f;font-weight:650}#setup .verifyPrivacy>i{color:#6d582e;font-style:normal}#setup .verifyPrivacy>span:first-child{color:#d1aa5a;font-size:14px}
#setup button:focus-visible,#setup textarea:focus-visible,#setup select:focus-visible{outline:2px solid color-mix(in srgb,var(--deck-a,#58b9ff) 50%,var(--verify-gold-bright));outline-offset:3px}
@media(max-width:560px){#setup{padding-inline:0}#setup .verifyShell{margin-top:5px;padding:108px 18px 22px;border-radius:12px}#setup .verifyFrame{inset:7px}#setup .verifyArcaneRail{display:none}#setup .verifyManaAtmosphere{left:12px;right:12px;top:50px;height:205px}#setup .verifyManaWheel{width:138px;height:138px;top:-82px}#setup .verifyManaWheel .manaMark{transform:scale(.9)}#setup .manaMark.white{left:52px;top:8px}#setup .manaMark.blue{right:7px;top:49px}#setup .manaMark.black{right:25px;bottom:9px}#setup .manaMark.red{left:24px;bottom:9px}#setup .manaMark.green{left:5px;top:49px}#setup .verifyHero{padding-top:58px}#setup h2{font-size:clamp(37px,10.5vw,48px)}#setup .verifyLead{font-size:13px;margin-bottom:28px}#setup textarea{min-height:275px}#setup .legalityToolbar{grid-template-columns:1fr;gap:7px}#setup .importActions{gap:8px}#setup .verifyImportCard{grid-template-columns:44px minmax(0,1fr);gap:9px;min-height:84px;padding:11px 10px}#setup .verifyActionIcon{width:42px;height:42px;font-size:22px}#setup .verifyImportCard b{font-size:15px}#setup .verifyImportCard small{font-size:9px}#setup .verifyVaultRow{grid-template-columns:46px minmax(0,1fr) auto;padding-inline:11px}#setup .verifyDeckCta{min-height:96px;grid-template-columns:50px minmax(0,1fr);padding:13px 17px;gap:11px}#setup .verifyShield{width:48px;height:55px}#setup .verifyDeckCta b{font-size:29px}#setup .verifyDeckCta small{font-size:10px}}
@media(max-width:390px){#setup .verifyShell{padding-inline:15px}#setup .importActions{grid-template-columns:1fr}#setup .verifyImportCard{min-height:72px}#setup .verifyLead br{display:none}}
@media(prefers-reduced-motion:reduce){#setup .manaFlow{animation:none}#setup .verifyImportCard,#setup .verifyVaultRow,#setup .verifyDeckCta{transition:none}}
'''
css=css[:start]+NEW+css[next_comment:]
if css.count(START)!=1: raise SystemExit(f'expected one canonical Verify owner, got {css.count(START)}')
if '!important' in NEW: raise SystemExit('studio Verify owner must not use !important')
CSS.write_text(css)
print('Replaced canonical Verify shell with studio-quality owner.')
